--CONTABILIDAD

CREATE TABLE CONTABILIDAD.FACTURA (
    ID_FACTURA INT PRIMARY KEY,
    ID_VENTA INT FOREIGN KEY REFERENCES VENTA.VENTA(ID_VENTA),
    FECHA_EMISION DATE,
    TIPO_COMPROBANTE VARCHAR(30),
    NUMERO_COMPROBANTE VARCHAR(30),
    TOTAL DECIMAL(10,2)
);

CREATE TABLE CONTABILIDAD.PAGO (
    ID_PAGO INT PRIMARY KEY,
    ID_FACTURA INT FOREIGN KEY REFERENCES CONTABILIDAD.FACTURA(ID_FACTURA),
    FECHA_PAGO DATE,
    MONTO DECIMAL(10,2),
    METODO_PAGO VARCHAR(30)
);

CREATE TABLE CONTABILIDAD.GASTO (
    ID_GASTO INT PRIMARY KEY,
    DESCRIPCION VARCHAR(300),
    FECHA DATE,
    MONTO DECIMAL(10,2)
);

CREATE TABLE CONTABILIDAD.COSTO (
    ID_COSTO INT PRIMARY KEY,
    ID_PRODUCTO BIGINT FOREIGN KEY REFERENCES LOGISTICA.PRODUCTO(ID_PRODUCTO),
    DESCRIPCION VARCHAR(300),
    MONTO DECIMAL(10,2),
    FECHA DATE
);

CREATE TABLE RRHH.Aprobador (
    ID_Aprobador VARCHAR(10) PRIMARY KEY,
    Nombre VARCHAR(50),
    Apellidos VARCHAR(100),
    Cargo VARCHAR(100),
    Area VARCHAR(100)
);
CREATE TABLE LOGISTICA.APROBACIONES (
    ID_APROBACION INT IDENTITY(1,1) PRIMARY KEY,
    ID_SALIDA         INT         NOT NULL,
    FECHA_SOLICITUD   DATE        NOT NULL,
    FECHA_APROBACION  DATE        NOT NULL,
    ID_APROBADOR VARCHAR(10) NOT NULL,
    FOREIGN KEY (ID_SALIDA) REFERENCES LOGISTICA.SALIDA (ID_SALIDA)
    
);
GO
CREATE TABLE LOGISTICA.PRODUCTO_PROVEEDOR (
    ID_PRODUCTO BIGINT   NOT NULL,
    RUC         CHAR(11) NOT NULL,
    PRIMARY KEY (ID_PRODUCTO, RUC),
    FOREIGN KEY (ID_PRODUCTO) REFERENCES LOGISTICA.PRODUCTO (ID_PRODUCTO),
    FOREIGN KEY (RUC)         REFERENCES LOGISTICA.PROVEEDOR (RUC)
);
GO

CREATE TABLE LOGISTICA.DETALLE_ALMACEN (
    ID_ALMACEN INT PRIMARY KEY,
    NOMBRE VARCHAR(100),
    RESPONSABLE VARCHAR(100),
    TAMANO DECIMAL(10,2),
    SEDE VARCHAR(100)
);

CREATE TABLE LOGISTICA.STOCK_ALMACEN (
    ID_ALMACEN INT,
    ID_PRODUCTO BIGINT,
    UNIDADES INT,
    PRIMARY KEY (ID_ALMACEN, ID_PRODUCTO)
);

